//! Focused caret transaction tests. All inputs are generated by owned new-document
//! and table builders; no legacy fixture, external input, or Native build here.
const std = @import("std");
const a = std.testing.allocator;
const commands = @import("wasm/character_property_text_commands.zig");
const formatting = @import("model/formatting_patch.zig");

fn patch() formatting.Patch {
    var result: formatting.Patch = .{ .character = .{
        .bold = false,
        .italic = false,
        .text_color = 0,
        .underline_kind = .bottom,
        .strike_enabled = true,
    } };
    for (&result.fonts) |*font| font.* = .{ .name = "Caret Native Font" };
    return result;
}

fn h5Input(cell: bool) ![]u8 {
    const bytes = try @import("new_document/root.zig").hwp5(a);
    defer a.free(bytes);
    const session = try @import("hwp5/edit/style_preservation.zig").Session.open(a, bytes);
    defer session.close();
    try session.apply(.{ .split_paragraph = .{ .section = 0, .paragraph = 0, .at_unit = 16 } });
    if (cell) {
        var ids = try session.planTableIds(1);
        defer ids.deinit(a);
        var table = try @import("model/created_table.zig").create(a, ids.identity, ids.instance_id, try @import("model/table_creation_plan.zig").create(1, 1, 18000, 1800, 1), ids.paragraph_ids, .{ .paragraph = 0, .character = 0, .style = 0, .border_fill = 0 }, 1);
        defer table.deinit(a);
        _ = try table.replaceText(a, 0, 0, "AB", 100);
        try session.apply(.{ .stage_table = .{
            .section = 0,
            .paragraph = 1,
            .unit = 0,
            .table = &table,
            .options = .{
                .common = .{ .flags = 0x6a2211, .offset_x = 0, .offset_y = 0, .z_order = 0, .margins = .{ 0, 0, 0, 0 }, .prevent_page_break = false, .description = "Caret" },
                .table = .{ .page_break = 1, .repeat_header = false, .cell_spacing = 0, .margins = .{ 0, 0, 0, 0 } },
                .cell = .{ .layout = .observed8, .unknown = 0, .attributes = 0, .margins = .{ 0, 0, 0, 0 } },
            },
        } });
    } else try session.apply(.{ .splice_text = .{ .section = 0, .paragraph = 1, .start_unit = 0, .end_unit = 0, .utf8 = "AB" } });
    return (try session.save(a, .{ .allow_stale_layout = true })).bytes;
}

fn h5Lifecycle(cell: bool) !void {
    const bytes = try h5Input(cell);
    defer a.free(bytes);
    const Session = @import("hwp5/edit/style_preservation.zig").Session;
    const session = try Session.open(a, bytes);
    defer session.close();
    const flows = try session.paragraphFlow(a, 0);
    defer a.free(flows);
    var paragraph: usize = 1;
    if (cell) for (flows) |flow| {
        if (flow.host == .table_cell) {
            paragraph = flow.paragraph;
            break;
        }
    };
    const expected_host: @import("hwp5/edit/paragraph_flow_host.zig").Host = if (cell) .table_cell else .body;
    try std.testing.expectEqual(expected_host, flows[paragraph].host);
    var history = try @import("hwp5/edit/editor_history.zig").History.initV2(a, session, .{ .max_entries = 8 });
    defer history.deinit();
    const batch = try commands.buildRich(.hwp5, a, .{ .section = 0, .paragraph = paragraph, .start = 1, .end = 1, .text = "한😀" }, patch());
    defer a.free(batch);
    {
        var context: @import("hwp5/edit/style_preservation.zig").FormattingBatch = .{};
        try session.beginFormattingBatch(&context);
        defer session.endFormattingBatch(&context);
        try std.testing.expect(try history.applyBatch(session, batch));
    }
    const saved = try session.save(a, .{ .allow_stale_layout = true });
    defer a.free(saved.bytes);
    const reopened = try Session.open(a, saved.bytes);
    defer reopened.close();
    const ranges = try reopened.characterRanges(a, 0, paragraph);
    defer a.free(ranges);
    const shapes = try reopened.characterShapes(a);
    defer a.free(shapes);
    const faces = try reopened.fontFaces(a);
    defer @import("model/font_face_value.zig").deinit(a, faces);
    var found = false;
    for (ranges) |range| if (range.start_unit == 1 and range.end_unit == 4) {
        const shape = shapes[range.char_shape_id.?];
        const decoration = @import("hwp5/edit/character_decoration_compat.zig").resolve(shape);
        try std.testing.expectEqual(@as(u2, 1), decoration.underline_kind);
        try std.testing.expectEqual(@as(?bool, true), decoration.strike_enabled);
        try std.testing.expectEqual(@as(u32, 0), shape.text_color_raw);
        try std.testing.expect(!shape.bold and !shape.italic);
        for (shape.font_ids, 0..) |id, language| {
            var matched = false;
            for (faces) |face| if (@backingInt(face.language) == language and face.id == id) {
                try std.testing.expectEqualStrings("Caret Native Font", face.name.?);
                matched = true;
            };
            try std.testing.expect(matched);
        }
        found = true;
    };
    try std.testing.expect(found);
    try std.testing.expect(try history.undo(session));
    const undone = try session.save(a, .{ .allow_stale_layout = true });
    defer a.free(undone.bytes);
    try std.testing.expectEqualSlices(u8, bytes, undone.bytes);
    try std.testing.expect(try history.redo(session));
    const redone = try session.save(a, .{ .allow_stale_layout = true });
    defer a.free(redone.bytes);
    try std.testing.expectEqualSlices(u8, saved.bytes, redone.bytes);
}

test "caret rich authored body saves reopens and one-step history restores bytes" {
    try h5Lifecycle(false);
}
test "caret rich original source cell saves reopens and one-step history restores bytes" {
    try h5Lifecycle(true);
}

fn hxLifecycle(cell: bool) !void {
    std.debug.print("caret rich HX stage=new-document cell={any}\n", .{cell});
    const bytes = try @import("new_document/root.zig").hwpx(a);
    defer a.free(bytes);
    const editor = @import("hwpx/editor_session.zig");
    std.debug.print("caret rich HX stage=open-seed cell={any}\n", .{cell});
    var seed = try editor.open(a, bytes, .{});
    defer seed.deinit();
    std.debug.print("caret rich HX stage=setup-split-root cell={any}\n", .{cell});
    try std.testing.expect(try seed.splitParagraphAnchored(0, 1, 0, 0));
    std.debug.print("caret rich HX stage=setup-splice-body cell={any}\n", .{cell});
    try std.testing.expect(try seed.spliceAnchored(0, 2, 0, 0, "AB"));
    if (cell) {
        std.debug.print("caret rich HX stage=setup-prepare-table cell={any}\n", .{cell});
        var table = try @import("hwpx/created_table_prepare.zig").prepare(&seed, 0, 2, 0, 1, 1, 18000, 1800, .{ .paragraph = 0, .character = 0, .style = 0, .border_fill = 1 });
        defer table.deinit(a);
        _ = try table.replaceText(a, 0, 0, "AB", 100);
        std.debug.print("caret rich HX stage=setup-stage-table cell={any}\n", .{cell});
        try std.testing.expect(try @import("hwpx/created_table_session.zig").stage(&seed, 0, 2, 0, &table));
    }
    std.debug.print("caret rich HX stage=setup-save cell={any}\n", .{cell});
    const before = try seed.save();
    defer a.free(before);
    std.debug.print("caret rich HX stage=reopen-input cell={any}\n", .{cell});
    var session = try editor.open(a, before, .{});
    defer session.deinit();
    const paragraph: usize = if (cell) 3 else 2;
    std.debug.print("caret rich HX stage=can-edit-source cell={any}\n", .{cell});
    try std.testing.expect(try session.canEdit(0, paragraph));
    var history = try @import("hwpx/editor_history.zig").History.init(&session, 8, 16_000_000);
    defer history.deinit();
    const batch = try commands.buildRich(.hwpx, a, .{ .section = 0, .paragraph = paragraph, .start = 1, .end = 1, .text = "한😀" }, patch());
    defer a.free(batch);
    {
        var context: @import("hwpx/formatting_batch_context.zig").Context = .{};
        try session.beginFormattingBatch(&context);
        defer session.endFormattingBatch(&context);
        std.debug.print("caret rich HX stage=rich-transaction cell={any}\n", .{cell});
        try std.testing.expect(try history.applyBatch(&session, batch));
    }
    std.debug.print("caret rich HX stage=save-styled cell={any}\n", .{cell});
    const saved = try session.save();
    defer a.free(saved);
    var reopened = try editor.open(a, saved, .{});
    defer reopened.deinit();
    const spans = try @import("hwpx/character_style_snapshot.zig").read(&reopened, 0, paragraph);
    defer a.free(spans);
    var inserted_id: ?u32 = null;
    for (spans) |span| if (span.start_unit == 1 and span.end_unit == 4) {
        inserted_id = span.char_shape_id;
    };
    try std.testing.expect(inserted_id != null);
    // Applying the same semantic patch to the saved inserted range is a no-op:
    // this checks the actual persisted decoration/color/font ID semantics.
    try std.testing.expect(!try reopened.setCharacterProperties(0, paragraph, 1, 4, patch().character));
    for (0..7) |language| try std.testing.expect(!try reopened.setCharacterFontName(0, paragraph, 1, 4, @fromBackingInt(@intCast(language)), "Caret Native Font"));
    const text = try reopened.anchorText(0, paragraph);
    defer a.free(text);
    try std.testing.expectEqualStrings("A한😀B", text);
    try std.testing.expect(try history.undo(&session));
    const undone = try session.save();
    defer a.free(undone);
    try std.testing.expectEqualSlices(u8, before, undone);
    try std.testing.expect(try history.redo(&session));
    const redone = try session.save();
    defer a.free(redone);
    try std.testing.expectEqualSlices(u8, saved, redone);
}

test "caret rich HWPX authored body persists semantics and exact history bytes" {
    try hxLifecycle(false);
}
test "caret rich HWPX source cell persists semantics and exact history bytes" {
    try hxLifecycle(true);
}
